async function api(path, options={}) {
  const res=await fetch(path,{...options,headers:{'Content-Type':'application/json',...(options.headers||{})}});
  const data=await res.json(); if(res.status===401){location.assign('/login');throw new Error('관리자 로그인이 필요합니다.');} if(!res.ok) throw new Error(data.error || '요청에 실패했습니다.'); return data;
}
function flash(message, error=false) { notice.textContent=message; notice.className=error?'error':''; }
function field(name,label,value='',type='text',required=true) { return `<label>${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`; }
function signaturePad(canvas,clear){
  const ctx=canvas.getContext('2d');let drawing=false,signed=false;const point=e=>{const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)*canvas.width/r.width,(e.clientY-r.top)*canvas.height/r.height];};
  ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#111';canvas.onpointerdown=e=>{e.preventDefault();drawing=true;signed=true;canvas.setPointerCapture(e.pointerId);const [x,y]=point(e);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+.1,y+.1);ctx.stroke();};canvas.onpointermove=e=>{if(drawing){const [x,y]=point(e);ctx.lineTo(x,y);ctx.stroke();}};canvas.onpointerup=canvas.onpointercancel=()=>{drawing=false;};clear.onclick=()=>{ctx.clearRect(0,0,canvas.width,canvas.height);signed=false;};
  return ()=>{if(!signed)throw Error('시험 서명을 입력해 주세요.');return canvas.toDataURL('image/png');};
}
function showDialog(title, html, onSubmit) {
  $('#dialog-title').textContent=title; $('#dialog-body').innerHTML=html; $('#dialog-error').textContent='';
  $('#dialog-form button[type=submit]').textContent='저장';
  $('#dialog-form').onsubmit=async (e)=>{e.preventDefault(); try {await onSubmit(Object.fromEntries(new FormData(e.currentTarget))); dialog.close(); flash('저장했습니다.'); await render();} catch(err) {$('#dialog-error').textContent=err.message;} };
  dialog.showModal();
}
