  content.innerHTML=`<section class="panel"><div class="panel-head"><div><p class="muted">${esc(state.types[doc.type])} · ${esc(doc.date)}</p><h2>${esc(doc.title)}</h2></div><span class="status ${esc(doc.status)}">${esc(statusLabels[doc.status])}</span></div><p class="detail-body">${esc(doc.body)||'내용이 없습니다.'}</p>${educationDetail}${detailFields}${rowsDetail}${riskDetail}<div class="action-row"><button class="outline" id="back">목록</button>${['draft','rejected'].includes(doc.status)&&!(doc.type==='cost'&&Array.isArray(details.rows))?'<button class="outline" id="edit">수정</button>':''}${actions.map(([id,label])=>`<button class="primary" data-action="${id}">${label}</button>`).join('')}<button class="outline" id="print">인쇄</button></div><div class="history"><strong>처리 이력</strong>${events.length?events.map(e=>`<p>${esc(e.created_at)} · ${esc(statusLabels[e.from_status])} → ${esc(statusLabels[e.to_status])}</p>`).join(''):'<p>아직 처리 이력이 없습니다.</p>'}</div></section>`;
