  if(doc.type==='basic')content.querySelector('.action-row').insertAdjacentHTML('beforebegin',`<p>기본 서류 분류: ${esc(details.category||'미분류')} · 공개 범위: ${details.shared?'승인 후 전체 가상 현장':'작성 현장'}</p>`);
